style.css:
@-moz-document domain("roblox.com") {
:root {
  --glass: rgba(10, 10, 12, 0.62);
  --glass-strong: rgba(8, 8, 10, 0.86);
  --line: rgba(255, 255, 255, 0.09);
  --line-strong: rgba(255, 255, 255, 0.22);
  --text: #f2f2f2;
  --dim: #a9a9ad;
}

html { background: #000 !important; }
body, #rbx-body { background: transparent !important; }

#rbx-body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background:
    linear-gradient(90deg, rgba(0,0,0,.55) 0%, rgba(0,0,0,.2) 40%, rgba(0,0,0,.25) 100%),
    linear-gradient(0deg, rgba(0,0,0,.65) 0%, transparent 45%),
    url("data:image/jpeg;base64,") center / cover no-repeat,
    #000;
}

#theme-background, #wrap, #container-main, .content, #navigation-container,
.container-main, .game-home-page-container, footer, #footer-container, .container-footer {
  background: transparent !important;
}

#header, .rbx-header, .navbar-fixed-top {
  background: rgba(0, 0, 0, 0.55) !important;
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--line) !important;
  box-shadow: none !important;
}

#navigation, .rbx-left-col, #left-navigation-container nav, .left-nav {
  background: rgba(0, 0, 0, 0.45) !important;
  backdrop-filter: blur(10px);
  border-right: 1px solid var(--line) !important;
}

.section-content, .container-list > .section-content, .profile-container .section-content,
.dropdown-menu, .popover, .modal-content, .rbx-popover-content, .tab-content,
.game-main-content, .game-details-carousel-container, .item-details-info-content,
.chat-main, .friends-content, .messages-container, .settings-container .section-content {
  background: var(--glass) !important;
  border: 1px solid var(--line) !important;
  border-radius: 10px !important;
  backdrop-filter: blur(10px);
}

.dropdown-menu, .popover, .modal-content, .rbx-popover-content {
  background: var(--glass-strong) !important;
  border-color: var(--line-strong) !important;
}

.game-card-container, .grid-item-container, .item-card-container, .list-item {
  border-radius: 10px !important;
  transition: transform .15s ease, box-shadow .15s ease;
}
.game-card-container:hover, .item-card-container:hover {
  transform: translateY(-2px);
  box-shadow: 0 0 0 1px var(--line-strong), 0 8px 24px rgba(0,0,0,.6) !important;
}

.thumbnail-2d-container, .game-card-thumb-container, .item-card-thumb-container {
  border-radius: 8px !important;
}

input.form-control, .input-field, .form-control, textarea, select, .rbx-select, .search-input, #navbar-search-input {
  background: rgba(255, 255, 255, 0.05) !important;
  border: 1px solid var(--line) !important;
  color: var(--text) !important;
}
input.form-control:focus, .form-control:focus, textarea:focus {
  border-color: rgba(255,255,255,.5) !important;
  box-shadow: 0 0 0 2px rgba(255,255,255,.08) !important;
}

h1, h2, h3, .text-title, .container-header h2, .game-card-name {
  color: var(--text) !important;
}
.text-secondary, .text-label, .game-card-info, .text-description {
  color: var(--dim) !important;
}

::-webkit-scrollbar { width: 9px; height: 9px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: rgba(255,255,255,.18); border-radius: 9px; border: 2px solid transparent; background-clip: padding-box; }
::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,.35); background-clip: padding-box; border: 2px solid transparent; }
::selection { background: rgba(255,255,255,.25); color: #fff; }
}
